import{a as e,n as t,o as n,r,s as i}from"./app-C9M3NSvs.js";import{t as a}from"./plugin-vue_export-helper-BDNMzG2s.js";var o=JSON.parse(`{"path":"/program/program/front/css.html","title":"CSS","lang":"zh-CN","frontmatter":{"description":"CSS 什么是CSS CSS（Cascading Style Sheets，层叠样式表）是一种用于描述 HTML 或 XML 文档外观和格式的样式表语言。它允许开发者将样式与内容分离，使得网页的设计和维护更加简便。通过 CSS，开发者可以控制网页中的元素颜色、字体、布局、动画效果等。 CSS 的历史 1994 年: CSS 的概念由 Håkon Wiu...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"CSS\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/program/program/front/css.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"CSS"}],["meta",{"property":"og:description","content":"CSS 什么是CSS CSS（Cascading Style Sheets，层叠样式表）是一种用于描述 HTML 或 XML 文档外观和格式的样式表语言。它允许开发者将样式与内容分离，使得网页的设计和维护更加简便。通过 CSS，开发者可以控制网页中的元素颜色、字体、布局、动画效果等。 CSS 的历史 1994 年: CSS 的概念由 Håkon Wiu..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1734955114000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":2.18,"words":654},"filePathRelative":"program/program/front/css.md","autoDesc":true}`),s={name:`css.md`};function c(a,o,s,c,l,u){let d=i(`DocsAD`);return n(),t(`div`,null,[o[0]||=r(`<h1 id="css" tabindex="-1"><a class="header-anchor" href="#css"><span>CSS</span></a></h1><h2 id="什么是css" tabindex="-1"><a class="header-anchor" href="#什么是css"><span>什么是<a href="https://www.w3schools.com/css/default.asp" target="_blank" rel="noopener noreferrer">CSS</a></span></a></h2><p>CSS（Cascading Style Sheets，层叠样式表）是一种用于描述 HTML 或 XML 文档外观和格式的样式表语言。它允许开发者将样式与内容分离，使得网页的设计和维护更加简便。通过 CSS，开发者可以控制网页中的元素颜色、字体、布局、动画效果等。</p>`,3),e(d),o[1]||=r(`<h2 id="css-的历史" tabindex="-1"><a class="header-anchor" href="#css-的历史"><span>CSS 的历史</span></a></h2><ul><li><p><strong>1994 年</strong>: CSS 的概念由 Håkon Wium Lie 提出。当时，他正在 CERN（欧洲核子研究中心）与万维网的发明者 Tim Berners-Lee 一起工作。</p></li><li><p><strong>1996 年 12 月</strong>: W3C（万维网联盟）发布了 CSS1 规范，这是 CSS 的第一个正式版本。CSS1 支持字体、颜色、对齐方式、边距和文本样式等基本功能。</p></li><li><p><strong>1998 年 5 月</strong>: CSS2 规范发布。相比 CSS1，CSS2 增加了定位、媒体类型、样式表导入、和伪类等功能。</p></li><li><p><strong>2001 年</strong>: CSS2.1 规范发布，对 CSS2 进行了修订和精简，修复了一些错误，进一步提高了浏览器兼容性。</p></li><li><p><strong>1999 年 至今</strong>: CSS3 是 CSS 的最新发展版本，采用模块化设计，不断添加新特性，如圆角、阴影、渐变、动画、弹性盒模型（Flexbox）等。CSS3 模块化的设计使得各个功能模块可以独立发布和更新。</p></li><li><p><strong>未来</strong>: 随着 Web 技术的不断发展，CSS 继续演变，引入了更多现代化的功能，如 CSS Grid、变量（Custom Properties）、容器查询等，为开发者提供了更强大的设计和布局工具。</p></li></ul><h2 id="css-预编译框架" tabindex="-1"><a class="header-anchor" href="#css-预编译框架"><span>CSS 预编译框架</span></a></h2><p>CSS 预编译框架是一种工具，允许开发者使用更高级的语法编写 CSS 代码，并在开发过程中生成标准的 CSS 文件。预编译器添加了变量、嵌套规则、函数和其他编程结构，使 CSS 更加灵活和可维护。</p><h3 id="_1-sass-scss" tabindex="-1"><a class="header-anchor" href="#_1-sass-scss"><span>1. Sass(Scss)</span></a></h3><ul><li><strong>全称</strong>: Syntactically Awesome Stylesheets</li><li><strong>特点</strong>: <ul><li>支持嵌套规则、变量、混入（Mixins）和继承。</li><li>提供了两种语法：缩进语法（Sass）和 SCSS（Sassy CSS）。</li><li>广泛支持和活跃的社区，拥有丰富的扩展库。</li></ul></li><li><strong>官网</strong>: <a href="https://sass-lang.com" target="_blank" rel="noopener noreferrer">https://sass-lang.com</a></li></ul><h3 id="_2-less" tabindex="-1"><a class="header-anchor" href="#_2-less"><span>2. Less</span></a></h3><ul><li><strong>特点</strong>: <ul><li>类似于 Sass，支持嵌套、变量和混入。</li><li>更加接近原生 CSS 语法，易于学习和上手。</li><li>最早由 Twitter Bootstrap 使用，后来被广泛采用。</li></ul></li><li><strong>官网</strong>: <a href="http://lesscss.org" target="_blank" rel="noopener noreferrer">http://lesscss.org</a></li></ul><h3 id="_3-stylus" tabindex="-1"><a class="header-anchor" href="#_3-stylus"><span>3. Stylus</span></a></h3><ul><li><strong>特点</strong>: <ul><li>提供极简的语法，甚至可以省略大括号和分号。</li><li>支持函数、变量、混入和条件语句。</li><li>灵活性强，允许开发者根据需要选择使用不同的语法风格。</li></ul></li><li><strong>官网</strong>: <a href="https://stylus-lang.com" target="_blank" rel="noopener noreferrer">https://stylus-lang.com</a></li></ul>`,10)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};